<template>
  <div class="page-shell" v-loading="loading">
    <div class="live-toolbar surface"><div><b>设备实时遥测</b><span>真实设备与虚拟设备使用同一数据视图</span></div><el-select v-model="deviceId" placeholder="选择已绑定设备" @change="poll"><el-option v-for="d in devices" :key="d.device_id" :label="`${d.device_name} · ${d.device_id}`" :value="d.device_id"/></el-select></div>
    <template v-if="live?.display"><section class="link surface"><div><i :class="live.link_state.toLowerCase()"></i><span>链路状态</span><b>{{ linkName(live.link_state) }}</b></div><div><span>设备状态</span><b>{{ live.device_state }}</b></div><div><span>任务 / 烟田</span><b>{{ live.inspection_id || '无任务' }}<small>{{ live.field_id || '—' }}</small></b></div><div><span>最近更新</span><b>{{ time(live.received_at) }}<small>{{ live.age_ms }} ms</small></b></div></section>
      <section class="panels"><article v-for="panel in panels" :key="panel.title" class="surface"><h3>{{ panel.title }}</h3><dl><div v-for="row in panel.rows" :key="row[0]"><dt>{{ row[0] }}</dt><dd>{{ row[1] }}</dd></div></dl></article></section>
      <section class="surface raw"><button @click="showRaw=!showRaw">{{ showRaw?'收起':'展开' }}原始 JSON</button><pre v-if="showRaw">{{ JSON.stringify(live.raw,null,2) }}</pre></section>
    </template><div v-else class="surface empty"><h3>{{ deviceId?'尚无设备数据':'请选择设备' }}</h3><p>{{ deviceId?'设备上报首条 V1.3 数据后，这里会显示原始值与平滑展示值。':'真实设备与虚拟设备共用同一页面。' }}</p></div>
  </div>
</template>
<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref } from 'vue';import { deviceApi } from '@/api/device';import { fieldApi } from '@/api/field';import type { DeviceItem,LiveData } from '@/types'
const loading=ref(true),devices=ref<DeviceItem[]>([]),deviceId=ref(''),live=ref<LiveData|null>(null),showRaw=ref(false);let timer:number|undefined
const v=computed(()=>live.value?.display||{} as any),fmt=(x:any,u='')=>x==null?'—':`${typeof x==='number'?x.toFixed(2):x}${u}`
const panels=computed(()=>[{code:'POSITION',title:'GPS / RTK',rows:[['经度',fmt(v.value.location?.longitude)],['纬度',fmt(v.value.location?.latitude)],['RTK',fmt(v.value.location?.rtk_status)],['高度',fmt(v.value.location?.altitude_msl_m,' m')],['速度',fmt(v.value.location?.ground_speed_mps,' m/s')],['航向',fmt(v.value.location?.course_over_ground_deg,'°')]]},{code:'MISSION',title:'任务进度',rows:[['序号',fmt(v.value.sequence)],['进度',fmt((v.value.flight_status?.progress||0)*100,'%')],['阶段',fmt(v.value.flight_status?.phase)],['待同步',fmt(v.value.pending_sync_count||0)]]},{code:'ENVIRONMENT',title:'环境',rows:[['温度',fmt(v.value.environment?.temperature,'°C')],['湿度',fmt(v.value.environment?.humidity,'%')],['CO₂',fmt(v.value.environment?.co2,' ppm')],['光照',fmt(v.value.environment?.light,' lux')]]},{code:'EDGE SYSTEM',title:'边缘设备',rows:[['CPU',fmt(v.value.device_status?.cpu_usage,'%')],['内存',fmt(v.value.device_status?.memory_usage,'%')],['温度',fmt(v.value.device_status?.temperature,'°C')],['存储',fmt(v.value.device_status?.storage_usage,'%')],['网络',fmt(v.value.device_status?.network_status)]]}])
async function poll(){if(!deviceId.value)return;try{live.value=await fieldApi.live(deviceId.value)}finally{loading.value=false}}
function linkName(s:string){return({LIVE:'实时',DELAYED:'数据延迟',DISCONNECTED:'链路中断',NO_DATA:'暂无数据'} as Record<string,string>)[s]||s}function time(x?:string|null){return x?new Date(x).toLocaleTimeString('zh-CN'):'—'}
onMounted(async()=>{devices.value=await deviceApi.list();deviceId.value=devices.value[0]?.device_id||'';await poll();timer=window.setInterval(poll,1000)});onBeforeUnmount(()=>timer&&clearInterval(timer))
</script>
<style scoped>
.page-intro .el-select{width:280px}.link{display:grid;grid-template-columns:repeat(4,1fr);margin-bottom:14px}.link>div{padding:18px;border-right:1px solid var(--line);position:relative}.link span{display:block;color:#7f8b83;font-size:9px}.link b{display:block;font:500 13px var(--mono);margin-top:7px}.link small{display:block;color:#8d9791;font:8px var(--mono);margin-top:4px}.link i{position:absolute;right:15px;top:17px;width:8px;height:8px;border-radius:50%;background:#a0aaa4}.link i.live{background:#70a95b;box-shadow:0 0 0 4px #dcebd5}.link i.delayed{background:#dda944}.link i.disconnected{background:#b5564b}.panels{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.panels article{padding:21px}.panels h3{font:600 18px var(--display);margin:6px 0 13px}.panels dl{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line)}.panels dl div{display:flex;justify-content:space-between;background:#f7f8f2;padding:11px}.panels dt{font-size:9px;color:#859087}.panels dd{font:10px var(--mono);margin:0}.raw{margin-top:14px;padding:18px}.raw button{border:0;background:#203a2c;color:white;padding:8px 12px;cursor:pointer}.raw pre{max-height:450px;overflow:auto;background:#17251f;color:#b9d7bd;padding:18px;font:10px/1.6 var(--mono)}.empty{text-align:center;padding:90px}.empty h3{font:600 20px var(--display)}.empty p{color:#7f8a83;font-size:11px}@media(max-width:850px){.link{grid-template-columns:1fr 1fr}.panels{grid-template-columns:1fr}}
.live-toolbar{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:16px 18px;margin-bottom:14px}.live-toolbar b,.live-toolbar span{display:block}.live-toolbar b{font-size:13px}.live-toolbar span{margin-top:4px;color:#839087;font-size:9px}.live-toolbar .el-select{width:280px}@media(max-width:850px){.live-toolbar{align-items:stretch;flex-direction:column}.live-toolbar .el-select{width:100%}}
</style>
<style scoped>
.live-toolbar{padding:18px 22px;margin-bottom:20px}.live-toolbar b{font-size:16px}.live-toolbar span{font-size:12px;color:#66776c}.link{overflow:hidden;margin-bottom:20px}.link>div{padding:18px 22px;min-width:0}.link>div:last-child{border:0}.link span{font-size:12px}.link b{font:500 15px var(--display);overflow-wrap:anywhere}.link small{font-size:11px}.panels{gap:20px}.panels article{padding:22px}.panels h3{font-size:17px;margin:0 0 18px}.panels dl{background:none;gap:0 20px;margin:0}.panels dl div{padding:12px 0;background:none;border-bottom:1px solid var(--line);gap:12px}.panels dt{font-size:12px;flex-shrink:0;color:#617168}.panels dd{font:500 14px var(--display);font-variant-numeric:tabular-nums;text-align:right;overflow-wrap:anywhere}.raw{margin-top:20px}.raw button{background:#eef4ef;color:var(--moss);border-radius:7px;font-size:13px}.raw pre{font-size:12px;border-radius:8px}.empty p{font-size:14px}
@media(max-width:600px){.panels dl{grid-template-columns:1fr}.link>div{padding:16px}.live-toolbar{padding:18px}.link{grid-template-columns:1fr 1fr}}
</style>
